function stepGame(state, event) {
  const next = { ...state };
  if (next.status === 'over') return next;

  if (event.type === 'catch') next.score += 10;
  else if (event.type === 'miss') next.lives = Math.max(0, next.lives - 1);

  next.level = Math.floor(next.score / 50) + 1;
  if (next.lives === 0) next.status = 'over';
  return next;
}
